// Classic Closure for Data Privacy
function createBankCounter(initialBalance) {
  // This variable is completely inaccessible from the outside world!
  let balance = initialBalance; 

  return {
    deposit: function(amount) {
      balance += amount;
      return balance;
    }
  };
}

// The outer function finishes executing here
const myAccount = createBankCounter(100);

// But the inner function 'deposit' still remembers 'balance'!
console.log(myAccount.deposit(50)); // 150
